#include "vintage/presets/VintagePresets.h"

#include "FactoryData.h" // generated by juce_add_binary_data (CMakeLists.txt): presets/factory/*.json
#include "vintage/params/ParameterLayout.h"

namespace vs
{
presets::Schema makeVintageSchema (const juce::AudioProcessor& processor)
{
    return presets::Schema::fromProcessor (processor, { kLowerPrefix, kUpperPrefix }, { ParamID::masterVolume });
}

presets::Bank makeVintageFactoryBank (const presets::Schema& schema, juce::StringArray* errors)
{
    std::vector<presets::FactoryFile> files;
    for (int i = 0; i < vs_factory::namedResourceListSize; ++i)
    {
        int size = 0;
        const char* name = vs_factory::namedResourceList[i];
        const char* data = vs_factory::getNamedResource (name, size);
        files.push_back ({ juce::String::fromUTF8 (vs_factory::getNamedResourceOriginalFilename (name)), data, static_cast<size_t> (size) });
    }
    return presets::makeBankFromFiles (schema, "Factory", files, errors);
}
} // namespace vs
